"""Verify that a raw result was generated by the checked-out sources."""

import argparse
import json
from pathlib import Path

from cv_mb_qrc.reservoirs.results import verify_source_hashes


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("path", type=Path)
    args = parser.parse_args()
    record = json.loads(args.path.read_text(encoding="utf-8"))
    verify_source_hashes(record.get("environment", record))
    print("source hashes verified")


if __name__ == "__main__":
    main()
